"""Inspect full articles before excluding two older Qian bibliography candidates."""
import json
import ledger as L
from review_batch_0001 import evidence

def main():
 before=L.counts();rid='author-priority-lulu-qian';batch='AUTHOR0007';base=L.ROOT/'assets/research-20261105'
 cases=[('10.1016/j.bbrc.2006.12.121','Brain-derived neurotrophic factor and risk of schizophrenia: An association study and meta-analysis','qian2007-bdnf.pdf','https://www.dna.caltech.edu/~lulu/S0006291X06027550.pdf','2006-12-22','Explicit Available online date, p738;2007 issue','pp738–742 abstract, Subjects/Genotyping/Statistical analysis, results and discussion; references pp742–743','Study genotypes BDNF polymorphisms in617 cases and672 controls and performs a16study meta-analysis. Methods use genomic DNA extraction, sequencing, ligase detection and capillary electrophoresis; results are genotype/haplotype associations. No authored, modified or reused origami object is presented. Exclusion follows inspected methods/results, not title keywords.',15,6),('10.1007/s11434-007-0230-0','DNA addition using linear self-assembly','qian2007-dna-addition.pdf','https://link.springer.com/content/pdf/10.1007/s11434-007-0230-0.pdf','2007-06','Issue month in primary PDF; exact first-online date unresolved','pp1462–1467; sections1.1–1.5 algorithm/library/experimental example, section2 wet-lab results, section3 discussion','DNA computing experiment uses short constraint oligonucleotides assembled into linear duplexes, ligated and PCR-amplified to encode binary sums. Each constraint strand contains20mer CS and H elements; four-bit example yields about200bp PCR product. This is oligonucleotide computation, not folding an origami scaffold or reusing an origami object. Appendices contain input libraries/results but are not acquired; their absence does not obscure the experimentally described assembly architecture.',16,7)]
 pubs={p['registry_key']:p for p in L.read('publication_reviews')};keys=[];audit=[];invpath=L.HERE/'qian_bibliography_inventory.json';inv=json.loads(invpath.read_text())
 for key,title,file,url,date,meaning,locator,note,cv,hist in cases:
  ev=evidence(base/file,url,locator);keys.append(key)
  p=pubs.get(key,dict(registry_key=key,registry_id=None,doi=key,canonical_work_id='work:'+key,canonical_work_status='provisional_unreconciled',version_links=[],legacy_record={},evidence=[]))
  if ev not in p['evidence']:p['evidence'].append(ev)
  p.update(title=title,publication_type=['journal_article'],review_stage='fulltext_reviewed',relevance='not_origami',design_contributions=[],catalog_eligibility='excluded',exclusion_reason='No DNA-origami design presented, modified or reused in inspected primary article',access='main_text_available',rationale=note,reviewer='Codex fulltext scope review',run_id=rid,date=L.DATE,date_evidence={'date':date,'source':ev,'primary_verified':True,'meaning':meaning},temporal_scope='pre2020_verified',unresolved_questions=[] if cv==15 else ['Exact first-online date unresolved; issue securely pre2020. Appendices not acquired; main architecture supports scope exclusion.'])
  L.upsert('publication_reviews',p,'Evidence-based non-origami disposition after low-keyword author-history review')
  audit.append(dict(key=key,decision='not_origami; catalog_excluded',checked_sections=locator,rationale=note,evidence=ev))
  for source,number,field in [('cv2019',cv,'cv_refereed'),('historical',hist,'historical_entries')]:
   row=next(r for r in inv[field] if r['number']==number);row.update(target_key=key,identity_status='primary_article_verified',review_status='fulltext_non_origami')
   e=next(e for e in L.read('discovery_edges') if e['edge_id']==rid+':'+source+':'+str(number));e.update(target_key=key,reconciliation_state='primary_identity_and_non_origami_scope_verified');L.upsert('discovery_edges',e,'Retain excluded candidate identity and evidence')
 L.atomic(invpath,json.dumps(inv,indent=2)+'\n')
 archives=json.loads((L.HERE/'shih_source_archive_inventory.json').read_text());invshihpath=L.HERE/'shih_bibliography_inventory.json';sh=json.loads(invshihpath.read_text())
 for a in archives:
  row=next(r for r in sh['entries'] if r['ordinal']==a['ordinal']);row.update(source_acquisition=a['archive'],source_content_status=a['content_status'],scientific_files=a['scientific_files'])
 L.atomic(invshihpath,json.dumps(sh,indent=2)+'\n')
 L.upsert('batches',dict(batch_id=batch,date=L.DATE,status='completed',input_keys=keys,discovery_run_ids=['author-priority-william-shih',rid],selection='Full Shih official bibliography and Qian low-keyword rotation',completed_actions=['Enumerated83 Shih bibliography paragraphs; retained65 pre2020/boundary entries,40 exact DOI matches and65 distinct source links.','Downloaded4 author ZIPs:3 contain16 scientific files total, fourth contains no scientific file; saved hash inventory and extracted PDF texts.','Reviewed two low-keyword Qian articles from full texts; retained auditable non-origami exclusions.','Acquired2007 DNA-addition main PDF; alternative wound-healing repository PDF403 remains an acquisition gap.'],before_counts=before,after_counts=L.counts(),unresolved_keys=[],exclusion_audit={'sample':audit,'denominator':2,'meaning':'Both new exclusion decisions independently checked against methods/results and abstract','external_independent_reviewer':False},validation=[L.validate(),{'test':'test_shih_bibliography','passed':1}],next_queue=['Review Ponnuswamy2017 DN1–DN9 and ten sequence workbooks; reconcile MeRPy scaffold variants.','Review acquired Hahn2019 and Krieg2018 main/SI sources.','Recover Tellechea2015 main text after empty author ZIP; do not infer scope from DNA gel title.','Compare Shih bibliography with paginated HMS and DASH; reconcile25 unmatched entries and boundary dates.','Continue Qian missing supplements and author bibliography/source backlog.']), 'Save author discovery/acquisition and low-keyword fulltext exclusion audit')
 print(L.validate())
if __name__=='__main__':main()
